// Port of :core practice/VerbDrill.kt: lightning verb drill cards, checking and progress. Prompt and lists come from
// fixtures/prompts.json (generated by Kotlin).
import prompts from '../../../fixtures/prompts.json' with { type: 'json' };
import { MalformedResponse, jsonCandidates } from './gloss.ts';
import { SUBJECTS, type Subject, TENSES, type VerbTense, subjectLabel } from './practice.ts';

export interface CommonVerb { infinitive: string; meaning: string }
export interface DrillCard {
  id: string; verb: string; tense: string; subject: string; english: string; spanish: string; answer: string; also: string[];
}
export interface DrillProgress { cardId: string; correct: number; misses: number; lastMillis: number; hidden: boolean }
export type DrillVerdict = 'correct' | 'accent' | 'wrong';
export type Situation = [VerbTense, Subject];

export const COMMON_VERBS: CommonVerb[] = prompts.commonVerbs;
export const DRILL_SYSTEM: string = prompts.drillSystem;
export const DRILL_REVIEW_SYSTEM: string = prompts.drillReviewSystem;
export const TO_LEARN: number = prompts.drillToLearn;
export const CARDS_PER_VERB: number = prompts.drillCardsPerVerb;
export const BLANK = '___';

type Rand = () => number;
const tense = (id: string) => TENSES.find((t) => t.id === id)!;
const subject = (id: string) => SUBJECTS.find((s) => s.id === id)!;
const pick = <T>(xs: T[], rand: Rand) => xs[Math.floor(rand() * xs.length)];
function shuffled<T>(xs: T[], rand: Rand): T[] {
  const a = [...xs];
  for (let i = a.length - 1; i > 0; i--) {
    const j = Math.floor(rand() * (i + 1));
    [a[i], a[j]] = [a[j], a[i]];
  }
  return a;
}

export const tenseLabel = (c: DrillCard) => TENSES.find((t) => t.id === c.tense)?.label ?? c.tense;
export const cardSubjectLabel = (c: DrillCard) => {
  const s = SUBJECTS.find((x) => x.id === c.subject);
  return s ? subjectLabel(s) : c.subject;
};
export const filled = (c: DrillCard) => c.spanish.replace(BLANK, c.answer);
/** The situation number in the id (`ir#3` → 3). */
export const cardNumber = (c: DrillCard) => Number.parseInt(c.id.slice(c.id.lastIndexOf('#') + 1), 10) || 0;

/** CARDS_PER_VERB distinct (tense, subject) pairs: the core set plus one less common form. */
export function situations(rand: Rand = Math.random): Situation[] {
  const ids = [...(prompts.drillSet as string[]), pick(prompts.drillExtra as string[], rand)];
  const used = new Set<string>();
  return ids.map((id) => {
    const t = tense(id);
    const subj = shuffled(t.subjects, rand).find((s) => !used.has(`${id}|${s}`)) ?? pick(t.subjects, rand);
    used.add(`${id}|${subj}`);
    return [t, subject(subj)];
  });
}

export function drillUserPrompt(verb: CommonVerb, sits: Situation[], isRetry = false): string {
  const o = {
    verb: verb.infinitive, verbMeaning: verb.meaning,
    situations: sits.map(([t, s], i) => ({ n: i + 1, tense: t.label, tenseNote: t.instruction, subject: subjectLabel(s) })),
  };
  return 'Write the cards:\n' + JSON.stringify(o) + (isRetry ? '\nYour previous reply could not be parsed. Reply with valid JSON only.' : '');
}

const trimEnds = (s: string) => s.replace(/^[\s.,!?¡¿;:"]+|[\s.,!?¡¿;:"]+$/g, '');
const clean = (s: string) => trimEnds(s.normalize('NFC')).replace(/\s+/g, ' ');
const norm = (s: string) => clean(s).toLowerCase();
const plain = (s: string) => norm(s).normalize('NFD').replace(/[̀-ͯ]/g, '');
const str = (o: Record<string, unknown>, k: string) => (typeof o[k] === 'string' && (o[k] as string).trim() ? (o[k] as string).trim() : null);

// No lookbehind (older Safari): group 2 is the helper.
const HELPERS = new RegExp(
  '(^|[^\\p{L}])((?:(?:he|has|ha|hemos|han|había|habías|habíamos|habían|habré|habrás|habrá|habremos|habrán|habría|habrías|habríamos|habrían|' +
  'estoy|estás|está|estamos|están|estaba|estabas|estábamos|estaban)|(?:voy|vas|va|vamos|van|iba|ibas|íbamos|iban)\\s+a)\\s+)$', 'iu');

const A_INFINITIVE = /^\s+(a)\s+(\p{L}*(?:ar|er|ir|ír))(?!\p{L})/iu;

/** "Mañana ___ a ir al cine." with "vas": the "a ir" that follows belongs to the verb form too. */
function helperAfter(card: DrillCard): DrillCard {
  if (card.answer.includes(' ')) return card;
  const cut = card.spanish.indexOf(BLANK) + BLANK.length;
  const after = card.spanish.slice(cut);
  const m = A_INFINITIVE.exec(after);
  if (!m) return card;
  const tail = ` ${m[1].toLowerCase()} ${m[2]}`;
  return {
    ...card, spanish: card.spanish.slice(0, cut) + after.slice(m[0].length), answer: card.answer + tail,
    also: card.also.map((a) => (a.includes(' ') ? a : a + tail)),
  };
}

/** Helper verbs around the blank go into the answer, so the blank always holds the whole verb form. */
export const withHelpers = (card: DrillCard) => helperAfter(helperBefore(card));

/** A helper verb left in front of the blank ("He ___" with "sido") goes into the answer ("he sido"). */
function helperBefore(card: DrillCard): DrillCard {
  const cut = card.spanish.indexOf(BLANK);
  const before = card.spanish.slice(0, cut);
  const m = HELPERS.exec(before);
  if (!m) return card;
  const helper = m[2].trim().replace(/\s+/g, ' ');
  const start = before.length - m[2].length;
  const spanish = card.spanish.slice(0, start) + card.spanish.slice(cut);
  const fix = (a: string) => (a.toLowerCase().startsWith(helper.toLowerCase() + ' ') ? a : `${helper.toLowerCase()} ${a}`);
  const answer = fix(card.answer);
  const capital = start === 0 && helper[0] !== helper[0].toLowerCase();
  return { ...card, spanish, answer: capital ? answer[0].toUpperCase() + answer.slice(1) : answer, also: card.also.map(fix) };
}

export function parseCards(text: string, verb: string, sits: Situation[]): DrillCard[] {
  for (const el of jsonCandidates(text)) {
    const arr = Array.isArray(el) ? el : (el as { cards?: unknown })?.cards;
    if (!Array.isArray(arr)) continue;
    const seen = new Set<string>();
    const cards: DrillCard[] = [];
    arr.forEach((item, i) => {
      if (typeof item !== 'object' || item === null) return;
      const o = item as Record<string, unknown>;
      const n = Number.parseInt(String(o.n ?? i + 1), 10) || i + 1;
      const sit = sits[n - 1];
      const english = str(o, 'english');
      const spanish = str(o, 'spanish')?.replace(/_{2,}/g, BLANK);
      const rawAnswer = str(o, 'answer');
      if (!sit || !english || !spanish || !rawAnswer) return;
      const answer = clean(rawAnswer);
      if (spanish.split(BLANK).length !== 2 || !answer) return;
      const also = (Array.isArray(o.also) ? o.also : []).filter((x): x is string => typeof x === 'string').map(clean)
        .filter((x) => x && x !== answer);
      const id = `${verb}#${n}`;
      if (seen.has(id)) return;
      seen.add(id);
      cards.push(withHelpers({ id, verb, tense: sit[0].id, subject: sit[1].id, english, spanish, answer, also }));
    });
    if (cards.length) return cards;
  }
  throw new MalformedResponse(`No drill cards in reply: ${text.slice(0, 200)}`);
}

export function reviewUserPrompt(verb: CommonVerb, cards: DrillCard[], isRetry = false): string {
  const o = {
    verb: verb.infinitive, verbMeaning: verb.meaning,
    cards: cards.map((c) => ({ n: cardNumber(c), tense: tenseLabel(c), subject: cardSubjectLabel(c), english: c.english, spanish: c.spanish, answer: c.answer, also: c.also })),
  };
  return 'Check these cards:\n' + JSON.stringify(o) + (isRetry ? '\nYour previous reply could not be parsed. Reply with valid JSON only.' : '');
}

/** [cards] after the review in [text]: corrected where the reviewer fixed them, without those it rejected or left out. */
export function applyReview(text: string, cards: DrillCard[]): DrillCard[] {
  for (const el of jsonCandidates(text)) {
    const arr = Array.isArray(el) ? el : (el as { cards?: unknown })?.cards;
    if (!Array.isArray(arr)) continue;
    const byNumber = new Map(cards.map((c) => [cardNumber(c), c]));
    const out = new Map<string, DrillCard>();
    for (const item of arr) {
      if (typeof item !== 'object' || item === null) continue;
      const o = item as Record<string, unknown>;
      const card = byNumber.get(Number.parseInt(String(o.n), 10));
      if (!card || String(o.ok) === 'false') continue;
      const spanish = str(o, 'spanish')?.replace(/_{2,}/g, BLANK) ?? card.spanish;
      const answer = (str(o, 'answer') && clean(str(o, 'answer')!)) || card.answer;
      if (spanish.split(BLANK).length !== 2) continue;
      const also = Array.isArray(o.also)
        ? o.also.filter((x): x is string => typeof x === 'string').map(clean).filter((x) => x && x !== answer) : card.also;
      if (!out.has(card.id)) out.set(card.id, withHelpers({ ...card, english: str(o, 'english') ?? card.english, spanish, answer, also }));
    }
    if (arr.length) return [...out.values()].sort((a, b) => cardNumber(a) - cardNumber(b));
  }
  throw new MalformedResponse(`No review in reply: ${text.slice(0, 200)}`);
}

export function checkDrill(card: DrillCard, typed: string): DrillVerdict {
  const t = norm(typed);
  const accepted = [card.answer, ...card.also];
  if (!t) return 'wrong';
  if (accepted.some((a) => norm(a) === t)) return 'correct';
  if (accepted.some((a) => plain(a) === plain(typed))) return 'accent';
  return 'wrong';
}

export function record(p: DrillProgress | undefined, cardId: string, correct: boolean, now: number): DrillProgress {
  const cur = p ?? { cardId, correct: 0, misses: 0, lastMillis: 0, hidden: false };
  return correct ? { ...cur, correct: cur.correct + 1, lastMillis: now }
    : { ...cur, correct: Math.max(0, cur.correct - 1), misses: cur.misses + 1, lastMillis: now };
}

export const isLearned = (p: DrillProgress | undefined) => !!p && (p.hidden || p.correct >= TO_LEARN);

export function round(cards: DrillCard[], progress: Map<string, DrillProgress>, rand: Rand = Math.random): DrillCard[] {
  const active = cards.filter((c) => !progress.get(c.id)?.hidden);
  const open = active.filter((c) => !isLearned(progress.get(c.id)));
  if (!open.length) return shuffled(active, rand);
  return shuffled(open, rand).sort((a, b) => (progress.get(a.id)?.correct ?? 0) - (progress.get(b.id)?.correct ?? 0));
}

export const mastered = (cards: DrillCard[], progress: Map<string, DrillProgress>) =>
  cards.length > 0 && cards.every((c) => isLearned(progress.get(c.id)));

export function currentVerb(cardsOf: (verb: string) => DrillCard[] | undefined, progress: Map<string, DrillProgress>): CommonVerb {
  return COMMON_VERBS.find((v) => !mastered(cardsOf(v.infinitive) ?? [], progress)) ?? COMMON_VERBS[COMMON_VERBS.length - 1];
}

export const answerWords = (c: DrillCard) =>
  [...new Set(c.answer.toLowerCase().split(' ').map((w) => w.trim()).filter((w) => w && /\p{L}/u.test(w)))];

type Complete = (system: string, user: string) => Promise<string>;

async function twice<T>(block: (retry: boolean) => Promise<T>): Promise<T> {
  try {
    return await block(false);
  } catch (e) {
    if (!(e instanceof MalformedResponse)) throw e;
    return block(true);
  }
}

/**
 * Writes a verb's cards with the AI, then has [review] (the stronger model where there is one) check and fix them.
 * Each step retries once on an unparseable reply; a review that never parses keeps the cards as written.
 */
export async function writeCards(complete: Complete, verb: CommonVerb, rand: Rand = Math.random, review: Complete = complete): Promise<DrillCard[]> {
  const sits = situations(rand);
  const written = await twice(async (retry) => parseCards(await complete(DRILL_SYSTEM, drillUserPrompt(verb, sits, retry)), verb.infinitive, sits));
  let reviewed: DrillCard[];
  try {
    reviewed = await twice(async (retry) => applyReview(await review(DRILL_REVIEW_SYSTEM, reviewUserPrompt(verb, written, retry)), written));
  } catch (e) {
    if (!(e instanceof MalformedResponse)) throw e;
    reviewed = written;
  }
  if (reviewed.length < CARDS_PER_VERB / 2) throw new MalformedResponse(`Only ${reviewed.length} usable cards for ${verb.infinitive}`);
  return reviewed;
}
